-- Fresh database baseline. Includes the Cafe77 menu from Item_Details_Report.xlsx.
-- Apply only to a new empty database. No staff accounts or passwords are seeded.

CREATE TABLE users(id INTEGER PRIMARY KEY, username TEXT UNIQUE NOT NULL, password TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','cashier')), active INTEGER NOT NULL DEFAULT 1, is_admin INTEGER NOT NULL DEFAULT 0);
CREATE TABLE sessions(token TEXT PRIMARY KEY,user_id INTEGER REFERENCES users(id),expires INTEGER NOT NULL);
CREATE TABLE tables(id INTEGER PRIMARY KEY,number INTEGER UNIQUE NOT NULL,token TEXT UNIQUE NOT NULL,active INTEGER NOT NULL DEFAULT 1,deleted_at TEXT);
CREATE TABLE groups(id INTEGER PRIMARY KEY,name TEXT NOT NULL,image TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1,sort INTEGER NOT NULL DEFAULT 0,deleted_at TEXT, counter_only INTEGER NOT NULL DEFAULT 0, customer_visible INTEGER NOT NULL DEFAULT 0);
CREATE TABLE menu(id INTEGER PRIMARY KEY,group_id INTEGER NOT NULL REFERENCES groups(id),code TEXT UNIQUE NOT NULL,name TEXT NOT NULL,price INTEGER NOT NULL CHECK(price>=0),details TEXT NOT NULL DEFAULT '',images TEXT NOT NULL DEFAULT '[]',video TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1,ran_out INTEGER NOT NULL DEFAULT 0,today_special INTEGER NOT NULL DEFAULT 0,dashboard_fav INTEGER NOT NULL DEFAULT 0,deleted_at TEXT, calories TEXT NOT NULL DEFAULT '', show_calories INTEGER NOT NULL DEFAULT 0, ingredients TEXT NOT NULL DEFAULT '', show_ingredients INTEGER NOT NULL DEFAULT 0);
CREATE TABLE orders(id INTEGER PRIMARY KEY,number TEXT UNIQUE NOT NULL,token TEXT UNIQUE NOT NULL,request_key TEXT UNIQUE NOT NULL,request_hash TEXT NOT NULL,table_id INTEGER NOT NULL REFERENCES tables(id),name TEXT NOT NULL,email TEXT NOT NULL DEFAULT '',phone TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'New',created_at TEXT NOT NULL,closed_at TEXT,version INTEGER NOT NULL DEFAULT 1,amounts TEXT NOT NULL,restaurant TEXT NOT NULL);
CREATE TABLE order_items(id INTEGER PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders(id),item_id INTEGER NOT NULL REFERENCES menu(id),code TEXT NOT NULL,name TEXT NOT NULL,price INTEGER NOT NULL,quantity INTEGER NOT NULL);
CREATE TABLE events(id INTEGER PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders(id),previous TEXT,status TEXT NOT NULL,reason TEXT NOT NULL DEFAULT '',actor TEXT NOT NULL,at TEXT NOT NULL);
CREATE TABLE payments(id INTEGER PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders(id),kind TEXT NOT NULL CHECK(kind IN ('payment','refund')),amount INTEGER NOT NULL CHECK(amount>0),actor TEXT NOT NULL,at TEXT NOT NULL);
CREATE TABLE audit(id INTEGER PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,details TEXT NOT NULL,at TEXT NOT NULL);
CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE transaction_guard(ok INTEGER NOT NULL CHECK(ok=1));
CREATE TABLE uploads(name TEXT PRIMARY KEY,content_type TEXT NOT NULL,size INTEGER NOT NULL);
CREATE TABLE upload_chunks(name TEXT NOT NULL REFERENCES uploads(name),position INTEGER NOT NULL,data BLOB NOT NULL,PRIMARY KEY(name,position));
CREATE TABLE rate_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE order_messages(id INTEGER PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders(id),sender TEXT NOT NULL CHECK(sender IN ('customer','staff')),text TEXT NOT NULL,at TEXT NOT NULL, read_at TEXT);
CREATE TABLE menu_history(id INTEGER PRIMARY KEY,menu_item_id INTEGER NOT NULL REFERENCES menu(id),item_code TEXT NOT NULL,item_name TEXT NOT NULL,changed_at TEXT NOT NULL,actor TEXT NOT NULL,change_type TEXT NOT NULL,system_comments TEXT NOT NULL,user_comments TEXT NOT NULL DEFAULT '',is_price_change INTEGER NOT NULL DEFAULT 0,old_price INTEGER,new_price INTEGER,old_ran_out INTEGER,new_ran_out INTEGER,old_today_special INTEGER,new_today_special INTEGER,old_dashboard_fav INTEGER,new_dashboard_fav INTEGER,old_active INTEGER,new_active INTEGER,before_json TEXT,after_json TEXT);
CREATE TABLE order_custom_items(id INTEGER PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders(id),name TEXT NOT NULL,price INTEGER NOT NULL CHECK(price>=0),quantity INTEGER NOT NULL CHECK(quantity>0),actor TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE tags(id INTEGER PRIMARY KEY,name TEXT NOT NULL,image TEXT NOT NULL DEFAULT '');
CREATE TABLE menu_tags(menu_item_id INTEGER NOT NULL REFERENCES menu(id),tag_id INTEGER NOT NULL REFERENCES tags(id),PRIMARY KEY(menu_item_id,tag_id));
CREATE INDEX orders_created ON orders(created_at DESC);
CREATE INDEX orders_status ON orders(status);
CREATE INDEX events_order ON events(order_id);
CREATE INDEX payments_order ON payments(order_id);
CREATE INDEX items_order ON order_items(order_id);
CREATE INDEX menu_group ON menu(group_id);
CREATE INDEX messages_order ON order_messages(order_id,id);
CREATE INDEX menu_history_date ON menu_history(changed_at DESC,id DESC);
CREATE INDEX menu_history_item ON menu_history(menu_item_id,changed_at DESC);
CREATE INDEX order_custom_items_order ON order_custom_items(order_id,id);
CREATE UNIQUE INDEX tags_name_unique ON tags(lower(name));
CREATE INDEX menu_tags_tag ON menu_tags(tag_id,menu_item_id);

WITH RECURSIVE numbers(n) AS (SELECT 1 UNION ALL SELECT n+1 FROM numbers WHERE n<15) INSERT INTO tables(number,token) SELECT n,lower(hex(randomblob(12))) FROM numbers;

